import { PayloadAction, createSlice } from "@reduxjs/toolkit";

// Define reusable types
interface APIResult<T = unknown> {
  status: number;
  result: T;
}

interface StateType {
  isOpen: boolean;
  isLoading: boolean;
  userListLoad: boolean;
  userListData: Record<string, unknown> | null;
  error: string | null;
  userAddressdata: unknown;
  addtocartLoad: boolean;
  addtocartData: unknown;
  loginLoad: boolean;
  loginData: unknown;
  siginLoad: boolean;
  siginData: unknown;
  updateuserLoad: boolean;
  updateuserData: unknown;
  updatecartLoad: boolean;
  updatecartData: unknown;
  getallProductLoad: boolean;
  getallProductData: unknown;
  getproductusingidLoad: boolean;
  getproductusingidData: unknown;
  getProductIdData: unknown;
  getCartListLoad: boolean;
  getCartData: unknown;
}

const initialState: StateType = {
  isOpen: false,
  isLoading: false,
  userListLoad: false,
  userListData: null,
  error: null,
  userAddressdata: null,
  addtocartLoad: false,
  addtocartData: null,
  loginLoad: false,
  loginData: null,
  siginLoad: false,
  siginData: null,
  updateuserLoad: false,
  updateuserData: null,
  updatecartLoad: false,
  updatecartData: null,
  getallProductLoad: false,
  getallProductData: null,
  getproductusingidLoad: false,
  getproductusingidData: null,
  getProductIdData: null,
  getCartListLoad: false,
  getCartData: null,
};

const bcl = createSlice({
  name: "bcl",
  initialState,
  reducers: {
    getUserAddressListLoad: (state) => {
      state.isOpen = true;
    },
    getUserAddressListSuccess: (
      state,
      action: PayloadAction<APIResult<{ getUserAddressListApi?: { addressDataList?: unknown } }>>
    ) => {
      state.isOpen = false;
      state.userAddressdata = action.payload.result?.getUserAddressListApi?.addressDataList;
    },

    getUserListLoad: (state) => {
      state.userListLoad = true;
    },
    getUserListSuccess: (
      state,
      action: PayloadAction<APIResult<Record<string, unknown>>>
    ) => {
      state.userListLoad = false;
      state.userListData = action.payload.result;
    },

    addtocartListload: (state) => {
      state.addtocartLoad = true;
    },
    addtocartListSuccess: (state, action: PayloadAction<APIResult>) => {
      state.addtocartLoad = false;
      state.addtocartData = action.payload.result;
    },

    loginListLoad: (state) => {
      state.loginLoad = true;
    },
    loginSuccess: (state, action: PayloadAction<APIResult>) => {
      state.loginLoad = false;
      state.loginData = action.payload.result;
    },

    siginListLoad: (state) => {
      state.siginLoad = true;
    },
    siginSuccess: (state, action: PayloadAction<APIResult>) => {
      state.siginLoad = false;
      state.siginData = action.payload.result;
    },

    updateuserListLoad: (state) => {
      state.updateuserLoad = true;
    },
    updateuserSuccess: (state, action: PayloadAction<APIResult>) => {
      state.updateuserLoad = false;
      state.updateuserData = action.payload.result;
    },

    getallproductListLoad: (state) => {
      state.getallProductLoad = true;
    },
    getallprodctSuccess: (state, action: PayloadAction<APIResult>) => {
      state.getallProductLoad = false;
      state.getallProductData = action.payload.result;
    },

    getproductusingidListLoad: (state) => {
      state.getproductusingidLoad = true;
    },
    getproductusingidSuccess: (state, action: PayloadAction<APIResult>) => {
      state.getproductusingidLoad = false;
      state.getproductusingidData = action.payload.result;
    },

    getProductWiseIdLoad: (state, action: PayloadAction<unknown>) => {
      state.getProductIdData = action.payload;
    },

    getCartLoad: (state) => {
      state.getCartListLoad = true;
    },
    getCartSuccess: (state, action: PayloadAction<APIResult>) => {
      state.getCartListLoad = false;
      state.getCartData = action.payload.result;
    },

    updatecartListLoad: (state) => {
      state.updatecartLoad = true;
    },
    updatecartSuccess: (state, action: PayloadAction<APIResult>) => {
      state.updatecartLoad = false;
      state.updatecartData = action.payload.result;
    },

    resetTemporaryState: () => initialState,
  },
});

export const {
  getUserAddressListLoad,
  getUserAddressListSuccess,
  getUserListLoad,
  getUserListSuccess,
  addtocartListSuccess,
  addtocartListload,
  loginListLoad,
  loginSuccess,
  siginListLoad,
  siginSuccess,
  updateuserListLoad,
  updateuserSuccess,
  getallproductListLoad,
  getallprodctSuccess,
  getproductusingidListLoad,
  getproductusingidSuccess,
  getProductWiseIdLoad,
  getCartLoad,
  getCartSuccess,
  updatecartListLoad,
  updatecartSuccess,
  resetTemporaryState,
} = bcl.actions;

export default bcl.reducer;
