import ApiConstants from "@/Globals/ApiConstants";
import { message } from "antd";
import { SagaIterator } from "redux-saga";
import { call, put } from "redux-saga/effects";
import {
  addtocartListSuccess,
  getallprodctSuccess,
  getproductusingidSuccess,
  getUserAddressListSuccess,
  getUserListSuccess,
  loginSuccess,
  siginSuccess,
  updateuserSuccess,
  getCartSuccess,
} from "../reducer/indexSlice";
import { bclAxiosAPi } from "../http/Axios";

// ---------- TYPES ----------
interface ApiResponse<T> {
  status: number;
  result: {
    data: {
      data: T;
      message?: string;
    };
  };
}

interface Action<T> {
  payload: T;
}

// ---------- SHARED SAGAS ----------
function* failSaga<T>(result: ApiResponse<T>) {
  yield put({ type: ApiConstants.API_USER_FAIL });
  const msg = result?.result?.data?.message || ApiConstants.SOMETHING_WENT_WRONG;

  message.config({ duration: 1.5, maxCount: 1 });
  message.error(msg);
}

function* errorSaga(error: unknown) {
  yield put({
    type: ApiConstants.API_SR_ERROR,
    error,
    status: (error as { status?: number })?.status,
  });

  message.config({ duration: 1.5, maxCount: 1 });
  message.error(ApiConstants.SOMETHING_WENT_WRONG);
}

// ---------- SAGAS ----------
export function* getUserAddressListSaga(action: Action<unknown>): SagaIterator {
  try {
    const response: ApiResponse<unknown> = yield call(bclAxiosAPi.getUserAddressListAxios, action.payload);
    if (response.status === 1) {
      yield put(getUserAddressListSuccess({ status: response.status, result: response.result.data.data }));
    } else {
      yield call(failSaga, response);
    }
  } catch (error) {
    yield call(errorSaga, error);
  }
}

