export function* getProductsByQuerySaga(action: Action<{ name: string }>): SagaIterator {
  try {
    const response: ApiResponse<unknown> = yield call(bclAxiosAPi.getallproductListbyQueryAxios, action.payload.name);
    yield put({
      type: "GET_ALL_PRODUCT_LIST_BYQUERY_SUCCESS",
      payload: response.result.data,
    });
  } catch (error) {
    yield put({
      type: "GET_ALL_PRODUCT_LIST_BYQUERY_FAILURE",
      error,
    });
  }
}
