import ApiConstants from "@/Globals/ApiConstants";
import { http } from "./Http";
import { message } from "antd";

const baseURL = "https://api.purfull.com";

const loginUrl = `${baseURL}/api/e-commercelogin`;
const url = `${baseURL}/user/get-all-user`;
const Carturl = `${baseURL}/cart/createcart`;
const Loginurl = `${baseURL}/user/login`;
const siginurl = `${baseURL}/user/create-user`;
const updateuserurl = `${baseURL}/user/update-user`;
const getallproducturl = `${baseURL}/product/get-all-product`;
const getproductusingidurl = `${baseURL}/product/get-product`;
const getCartListurl = `${baseURL}/cart/get-cart`;
const updateCarturl = `${baseURL}/cart/updatecart`;

interface APIResponse {
  status: number;
  result?: unknown;
  error?: unknown;
}

interface Payload {
  [key: string]: unknown;
}

const Method = {
  async dataQuery(body: Payload, url: string): Promise<APIResponse> {
    try {
      const result = await http.post(
        url,
        { body },
        {
          headers: {
            "Content-Type": "application/json",
          },
        }
      );

      if (result.status === 200) {
        return { status: 1, result };
      } else if (result.status === 212) {
        return { status: 4, result };
      } else {
        return {
          status: 3,
          error: ApiConstants.SOMETHING_WENT_WRONG,
        };
      }
    } catch (err: unknown) {
      const error = err as { response?: { status?: number } };
      if (error?.response?.status === 401) {
        message.error("401 unauthorized");
        return { status: 5, error };
      }
      return { status: 5, error };
    }
  },

  async dataPut(body: Payload, url: string): Promise<APIResponse> {
    try {
      const result = await http.put(
        url,
        { body },
        {
          headers: {
            "Content-Type": "application/json",
          },
        }
      );

      if (result.status === 200) {
        return { status: 1, result };
      } else if (result.status === 212) {
        return { status: 4, result };
      } else {
        return {
          status: 3,
          error: ApiConstants.SOMETHING_WENT_WRONG,
        };
      }
    } catch (err: unknown) {
      const error = err as { response?: { status?: number } };
      if (error?.response?.status === 401) {
        message.error("401 unauthorized");
        return { status: 5, error };
      }
      return { status: 5, error };
    }
  },

  async get(url: string): Promise<APIResponse> {
    try {
      const result = await http.get(url, {
        headers: {
          "Content-Type": "application/json",
        },
      });

      if (result.status === 200) {
        return { status: 1, result };
      } else {
        return {
          status: 3,
          error: ApiConstants.SOMETHING_WENT_WRONG,
        };
      }
    } catch (err: unknown) {
      return {
        status: 5,
        error: err,
      };
    }
  },
};

const bclAxiosAPi = {
  getUserAddressListAxios: (payload: Payload) =>
    Method.dataQuery(payload, loginUrl),

  getUserListAxios: (payload: Payload) => Method.dataQuery(payload, url),

  addtoCartListAxios: (payload: Payload) =>
    Method.dataQuery(payload, Carturl),

  loginListAxios: (payload: Payload) => Method.dataQuery(payload, Loginurl),

  siginListAxios: (payload: Payload) => Method.dataQuery(payload, siginurl),

  updateuserListAxios: (payload: Payload) =>
    Method.dataPut(payload, updateuserurl),

  getallproductListAxios: () => Method.get(getallproducturl),

  getproductusingidListAxios: (payload: Payload) =>
    Method.dataQuery(payload, getproductusingidurl),

  getallproductListbyQueryAxios: (name: string) => {
    const urlWithQuery = `${getallproducturl}?name=${encodeURIComponent(name)}`;
    return Method.get(urlWithQuery);
  },

  getCartListtAxios: (payload: Payload) =>
    Method.dataQuery(payload, getCartListurl),

  updatecartListAxios: (payload: Payload) =>
    Method.dataPut(payload, updateCarturl),
};

export { bclAxiosAPi };
